   const ui=mountProgress(ref.current,{load:state(props.sessionId),setMode:setMode(props.sessionId),setAppearance:setAppearance(props.sessionId),setSummaryAppearance:setSummaryAppearance(props.sessionId),setDisplay:setDisplay(props.sessionId),setOutputPolicy:setOutputPolicy(props.sessionId),setFlowDirection:setFlowDirection(props.sessionId),importKey:importKey(props.sessionId),checkKey:checkKey(props.sessionId)});
